DB_PATH = str(secret("DB_PATH", os.getenv("DB_PATH", "farm_ledger.sqlite3")))
COLUMNS = ["id", "date", "kind", "category", "crop", "amount", "memo"]
CATS = {"수입": ["농산물 판매", "보조금", "체험·가공", "기타 수입"], "지출": ["종자·종묘", "비료·농약", "인건비", "농기계·수리", "유류·전기", "임차료", "포장·운송", "기타 지출"]}
ADDRESS_BLOB = ''

DATABASE_URL = str(secret("DATABASE_URL", os.getenv("DATABASE_URL", "")))

class Store:
    def __init__(self):
        self.remote=bool(DATABASE_URL)
        if self.remote:
            import psycopg
            self.raw=psycopg.connect(DATABASE_URL,connect_timeout=10,sslmode="require")
        else:
            self.raw=sqlite3.connect(DB_PATH,timeout=20)
        self.total_changes=0
    def execute(self,sql,args=()):
        if self.remote:sql=sql.replace("?","%s")
        cursor=self.raw.execute(sql,args)
        self.total_changes+=max(cursor.rowcount,0)
        return cursor
    def executemany(self,sql,rows):
        for row in rows:self.execute(sql,row)
    def __enter__(self):return self
    def __exit__(self,kind,value,tb):
        try:
            if kind:self.raw.rollback()
            else:self.raw.commit()
        finally:self.raw.close()

def connect():return Store()

